        let bInputs = Inputs.vectors(H.Vector.self, seed: 0x8DE2_CEE1_4BBD_C052)
        let cInputs = Inputs.vectors(H.Vector.self, seed: 0x8DE2_CDE1_4BBD_BE9F)
        let dInputs = Inputs.vectors(H.Vector.self, seed: 0x8DE2_CCE1_4BBD_BCEC)
        for (a, b, c, d) in mixedQuadruples(
            aInputs,
            bInputs,
            cInputs,
            dInputs,
            seed: 0xA70A_41BD_BF18_27F7
        ) {
            let (_, portLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                unsafe H.appendInterleaved4(a, b, c, d, toUnchecked: &output)
            }
            let (_, referenceLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                H.appendInterleaved4(a, b, c, d, to: &output)
            }
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), b: \(describe(b)), c: \(describe(c)), d: \(describe(d))"
            )
        }
        mismatches.record()
    }
}
